<script setup lang="ts">import {Head,Link,router} from '@inertiajs/vue3';import {ref} from 'vue';import PageHeader from '@/components/Shared/PageHeader.vue';import {Button} from '@/components/ui/button';const p=defineProps<{entries:any;filters:any;audiences:any[]}>();const search=ref(p.filters.search??'');const audience=ref(p.filters.audience??'');function apply(){router.get('/admin/page-help',{search:search.value,audience:audience.value},{preserveState:true,replace:true});}</script>
<template><Head title="Page Help"/><div class="space-y-6 p-6"><PageHeader title="Page Help" description="Manage contextual documentation by page key and audience"><template #actions><Button variant="outline" as-child><Link href="/admin/page-help/coverage">Coverage</Link></Button><Button as-child><Link href="/admin/page-help/create">Add Help</Link></Button></template></PageHeader><div class="flex flex-wrap gap-3 rounded-lg border bg-card p-4"><input v-model="search" @keyup.enter="apply" class="h-10 min-w-64 rounded-md border bg-background px-3" placeholder="Search key or title"/><select v-model="audience" class="h-10 rounded-md border bg-background px-3"><option value="">All audiences</option><option v-for="a in audiences" :key="a.value" :value="a.value">{{a.label}}</option></select><Button @click="apply">Filter</Button></div><div class="overflow-hidden rounded-lg border bg-card"><table class="w-full text-sm"><thead class="bg-muted/50 text-left"><tr><th class="p-3">Page key</th><th class="p-3">Title</th><th class="p-3">Audience</th><th class="p-3">State</th><th class="p-3 text-right">Actions</th></tr></thead><tbody><tr v-for="e in entries.data" :key="e.id" class="border-t"><td class="p-3 font-mono text-xs">{{e.page_key}}</td><td class="p-3"><div class="font-medium">{{e.title}}</div><div class="text-muted-foreground">{{e.summary}}</div></td><td class="p-3 capitalize">{{e.audience}}</td><td class="p-3">{{e.is_published?'Published':'Draft'}}<span v-if="!e.is_active"> · Inactive</span></td><td class="p-3 text-right"><Button size="sm" variant="outline" as-child><Link :href="`/admin/page-help/${e.id}/edit`">Edit</Link></Button></td></tr><tr v-if="!entries.data.length"><td colspan="5" class="p-8 text-center text-muted-foreground">No Page Help entries found.</td></tr></tbody></table></div></div></template>
